/* rpcstubs-test.cpp
 *
 * Typed RPC stubs generated by $C.rpcstubs: a client calls through
 * <Interface>_call_<method>, reads <Interface>_results_<method>, and the
 * server is a vtable routed by <Interface>_dispatch.
 */

#include <gtest/gtest.h>

#include <cstring>
#include <deque>
#include <vector>

extern "C" {
#include "capn-rpc.h"
#include "rpcstubs.capnp.h"
}

namespace {

struct Wire {
  std::deque<std::vector<uint8_t> > to_client, to_vat;
};
Wire *g_wire;

int to_vat(void *, const uint8_t *d, size_t n) {
  g_wire->to_vat.push_back(std::vector<uint8_t>(d, d + n));
  return 0;
}
int to_client(void *, const uint8_t *d, size_t n) {
  g_wire->to_client.push_back(std::vector<uint8_t>(d, d + n));
  return 0;
}

void pump(struct capn_rpc_conn *c, std::deque<std::vector<uint8_t> > &q) {
  while (!q.empty()) {
    std::vector<uint8_t> f = q.front();
    q.pop_front();
    capn_rpc_handle(c, f.data(), f.size());
  }
}

struct Calc {
  int adds = 0;
  int ticks = 0;
  uint64_t last_tick = 0;
};

int on_add(void *self, const struct Calc_add_params *in, struct Calc_add_results *out,
           struct capn_segment *) {
  static_cast<Calc *>(self)->adds++;
  out->sum = in->a + in->b;
  return 0;
}

int on_join(void *, const struct Calc_join_params *in, struct Calc_join_results *out,
            struct capn_segment *) {
  std::string joined = std::string(in->left.str ? in->left.str : "") +
                       (in->right.str ? in->right.str : "");
  /* write_ copies a text that does not live in the message. */
  static std::string keep;
  keep = joined;
  out->joined.str = keep.c_str();
  out->joined.len = static_cast<int>(keep.size());
  out->joined.seg = NULL;
  out->length = static_cast<uint32_t>(joined.size());
  return 0;
}

int on_noop(void *, const struct Calc_noop_params *, struct Calc_noop_results *,
            struct capn_segment *) {
  return 0;
}

int on_ticks(void *self, const struct Calc_ticks_params *in, struct capn_segment *) {
  Calc *c = static_cast<Calc *>(self);
  c->ticks++;
  c->last_tick = in->n;
  return 0;
}

class RpcStubs : public ::testing::Test {
 protected:
  void SetUp() override {
    wire = Wire();
    g_wire = &wire;
    capn_rpc_init(&client, to_vat, NULL);
    capn_rpc_init(&vat, to_client, NULL);
    calc = Calc();
    server.self = &calc;
    server.on_add = on_add;
    server.on_join = on_join;
    server.on_noop = on_noop;
    server.on_ticks = on_ticks;
    capn_rpc_set_bootstrap(&vat, &server, Calc_dispatch);
    capn_rpc_set_result_size(&vat, Calc_RESULT_DATASZ, Calc_RESULT_PTRS);
    capn_rpc_send_bootstrap(&client);
    settle();
  }
  void TearDown() override {
    capn_rpc_free(&client);
    capn_rpc_free(&vat);
  }
  void settle() {
    pump(&vat, wire.to_vat);
    pump(&client, wire.to_client);
  }

  Wire wire;
  struct capn_rpc_conn client, vat;
  struct Calc_server server;
  Calc calc;
};

}  // namespace

TEST_F(RpcStubs, ScalarCallRoundTrips) {
  struct Calc_add_params in;
  memset(&in, 0, sizeof in);
  in.a = 40;
  in.b = 2;
  uint32_t q = Calc_call_add(&client, 0, &in);
  ASSERT_NE((uint32_t) -1, q);
  settle();

  struct capn msg;
  struct Calc_add_results out;
  memset(&out, 0, sizeof out);
  ASSERT_EQ(0, Calc_results_add(&client, q, &out, &msg));
  EXPECT_EQ(42, out.sum);
  EXPECT_EQ(1, calc.adds);
  capn_free(&msg);
}

TEST_F(RpcStubs, TextParametersAndResults) {
  struct Calc_join_params in;
  memset(&in, 0, sizeof in);
  in.left.str = "foo";
  in.left.len = 3;
  in.right.str = "bar";
  in.right.len = 3;
  uint32_t q = Calc_call_join(&client, 0, &in);
  settle();

  struct capn msg;
  struct Calc_join_results out;
  memset(&out, 0, sizeof out);
  ASSERT_EQ(0, Calc_results_join(&client, q, &out, &msg));
  ASSERT_EQ(6, out.joined.len);
  EXPECT_EQ(0, memcmp(out.joined.str, "foobar", 6));
  EXPECT_EQ(6u, out.length);
  capn_free(&msg);
}

TEST_F(RpcStubs, EmptyParametersAndResults) {
  struct Calc_noop_params in;
  memset(&in, 0, sizeof in);
  uint32_t q = Calc_call_noop(&client, 0, &in);
  settle();
  EXPECT_TRUE(capn_rpc_is_answered(&client, q));
  EXPECT_FALSE(capn_rpc_is_failed(&client, q));
}

TEST_F(RpcStubs, StreamMethodHasNoResultReader) {
  struct Calc_ticks_params in;
  memset(&in, 0, sizeof in);
  in.n = 123456789012ULL;
  uint32_t q = Calc_call_ticks(&client, 0, &in);
  settle();
  EXPECT_FALSE(capn_rpc_is_failed(&client, q));
  EXPECT_EQ(1, calc.ticks);
  EXPECT_EQ(123456789012ULL, calc.last_tick);
}

TEST_F(RpcStubs, MissingHandlerOrWrongInterfaceFails) {
  server.on_add = NULL;
  struct Calc_add_params in;
  memset(&in, 0, sizeof in);
  uint32_t q = Calc_call_add(&client, 0, &in);
  settle();
  EXPECT_TRUE(capn_rpc_is_failed(&client, q));

  /* A call for another interface id reaches the dispatcher and is refused. */
  uint32_t q2 = capn_rpc_send_call(&client, 0, Echo_INTERFACE_ID, 0, 8, 1, NULL, NULL);
  settle();
  EXPECT_TRUE(capn_rpc_is_failed(&client, q2));
}

TEST_F(RpcStubs, SubclassRoutesSuperclassMethods) {
  struct SubCalc_server subclass;
  struct Calc_add_params in;
  Calc_add_params_ptr ip;
  struct Calc_add_results out;
  Calc_add_results_ptr op;
  struct capn msg;

  memset(&subclass, 0, sizeof subclass);
  subclass.super_Calc = &server;
  capn_init_malloc(&msg);
  memset(&in, 0, sizeof in);
  in.a = 19;
  in.b = 23;
  ip = new_Calc_add_params(capn_root(&msg).seg);
  write_Calc_add_params(&in, ip);
  op = new_Calc_add_results(capn_root(&msg).seg);

  ASSERT_EQ(0, SubCalc_dispatch(&subclass, Calc_INTERFACE_ID, 0, ip.p, op.p));
  memset(&out, 0, sizeof out);
  read_Calc_add_results(&out, op);
  EXPECT_EQ(42, out.sum);
  EXPECT_EQ(1, calc.adds);
  capn_free(&msg);
}
